args.new_string:
export async function getProjectTitle(slug: string) {
  'use cache'
  // A long-lived cache keeps the title resolvable at prefetch time, which is
  // what lets it arrive before the click.
  cacheLife('max')
  return projects[slug]?.title ?? 'Unknown project'
}

export async function getProjectDetails(slug: string) {
  'use cache'
  // Deliberately short-lived so the details stay out of prefetches: an `expire`
  // under 5 minutes excludes a cache from prerenders, making this a dynamic hole
  // that resolves at request time and streams into its <Suspense> fallback. The
  // result is still cached server-side, so it isn't refetched on every request.
  cacheLife({ stale: 60, revalidate: 60, expire: 240 })
  await new Promise((resolve) => setTimeout(resolve, 800))

